package de.mcstack.craftcore;
import java.sql.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class AuctionStoreTest {
  Connection setup(String name)throws Exception{Connection c=DriverManager.getConnection("jdbc:h2:mem:"+name+";MODE=MySQL;DB_CLOSE_DELAY=-1");try(Statement s=c.createStatement()){s.execute("CREATE TABLE ah_fee_journal(purchase_id VARCHAR(36) PRIMARY KEY,listing_id VARCHAR(36),buyer VARCHAR(36),seller VARCHAR(36),gross BIGINT,fee BIGINT,created_at BIGINT)");s.execute("CREATE TABLE pending_deliveries(id VARCHAR(36) PRIMARY KEY,player_uuid VARCHAR(36),item_nbt LONGTEXT,amount INT,source VARCHAR(32),status VARCHAR(16))");s.execute("CREATE TABLE accounts(uuid VARCHAR(36) PRIMARY KEY,balance BIGINT NOT NULL)");s.execute("CREATE TABLE ah_journal(id VARCHAR(36) PRIMARY KEY,seller VARCHAR(36),price BIGINT,status VARCHAR(16),recipient VARCHAR(36),expires_at BIGINT,item LONGTEXT,amount INT)");s.execute("INSERT INTO accounts VALUES('seller',0),('buyer',10000)");s.execute("INSERT INTO ah_journal VALUES('j','seller',1000,'OPEN',NULL,100,'item',1)");}c.setAutoCommit(false);return c;}
  long value(Connection c,String q)throws Exception{try(ResultSet r=c.createStatement().executeQuery(q)){assertTrue(r.next());return r.getLong(1);}}
  @Test void feeAndSinglePurchase()throws Exception{try(Connection c=setup("ah1")){assertNull(AuctionStore.buy(c,"j","buyer",99,500));c.commit();assertEquals(9000,value(c,"SELECT balance FROM accounts WHERE uuid='buyer'"));assertEquals(950,value(c,"SELECT balance FROM accounts WHERE uuid='seller'"));assertNotNull(AuctionStore.buy(c,"j","buyer",99,500));}}
  @Test void expiryCancelAndRollback()throws Exception{try(Connection c=setup("ah2")){assertNotNull(AuctionStore.buy(c,"j","buyer",100,500));assertNull(AuctionStore.buy(c,"j","buyer",99,500));c.rollback();assertTrue(AuctionStore.cancel(c,"j","seller"));assertFalse(AuctionStore.cancel(c,"j","seller"));assertEquals(10000,value(c,"SELECT balance FROM accounts WHERE uuid='buyer'"));}}
  @Test void changedPriceOrItemRejectsWithoutCharging()throws Exception {try(Connection c=setup("ah_changed")){c.createStatement().executeUpdate("UPDATE ah_journal SET price=1200 WHERE id='j'");assertNotNull(AuctionStore.buy(c,"j","buyer",99,500,1000L,"item"));assertEquals(10000,value(c,"SELECT balance FROM accounts WHERE uuid='buyer'"));assertEquals(0,value(c,"SELECT COUNT(*) FROM pending_deliveries"));assertNotNull(AuctionStore.buy(c,"j","buyer",99,500,1200L,"old item"));assertNull(AuctionStore.buy(c,"j","buyer",99,500,1200L,"item"));c.rollback();}}
}
